"""Core migration runner.

Design:
- Migrations are discovered from a directory, named ``NNN_description.py``.
  The numeric prefix is the version; ordering is by version number.
- Applied versions are recorded in ``schema_migrations(version, applied_at)``.
- ``upgrade()`` applies every pending migration in order, each wrapped in its
  own transaction together with its ``schema_migrations`` insert.
- ``downgrade(target)`` rolls back applied migrations with
  ``version > target``, newest first, each in its own transaction.
- ``status()`` renders a human-readable table of applied/pending migrations.

The runner takes ownership of transaction control on the connection it is
given (it switches sqlite3 to ``isolation_level=None`` so that explicit
``BEGIN``/``COMMIT``/``ROLLBACK`` behave predictably).
"""

from __future__ import annotations

import importlib.util
import re
import sqlite3
import sys
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from types import ModuleType


class MigrationError(RuntimeError):
    """Raised when a migration fails; the database is left untouched."""


@dataclass(frozen=True)
class Migration:
    version: int
    name: str
    path: Path

    @property
    def label(self) -> str:
        return f"{self.version:03d}_{self.name}"


class MigrationRunner:
    VERSION_TABLE = "schema_migrations"
    _FILENAME_RE = re.compile(r"^(\d+)_(\w+)\.py$")

    def __init__(self, conn: sqlite3.Connection, migrations_dir: str | Path):
        self.conn = conn
        self.migrations_dir = Path(migrations_dir)
        if not self.migrations_dir.is_dir():
            raise MigrationError(
                f"migrations directory not found: {self.migrations_dir}"
            )
        # Manual transaction control: no implicit BEGINs from the driver.
        self.conn.isolation_level = None
        self.conn.execute("PRAGMA foreign_keys = ON")
        self._ensure_version_table()

    # ------------------------------------------------------------- tracking

    def _ensure_version_table(self) -> None:
        self.conn.execute(
            f"""
            CREATE TABLE IF NOT EXISTS {self.VERSION_TABLE} (
                version     INTEGER PRIMARY KEY,
                applied_at  TEXT NOT NULL
            )
            """
        )

    def applied_versions(self) -> list[int]:
        rows = self.conn.execute(
            f"SELECT version FROM {self.VERSION_TABLE} ORDER BY version"
        ).fetchall()
        return [row[0] for row in rows]

    def current_version(self) -> int | None:
        versions = self.applied_versions()
        return versions[-1] if versions else None

    # ----------------------------------------------------------- discovery

    def discover(self) -> list[Migration]:
        found: dict[int, Migration] = {}
        for path in sorted(self.migrations_dir.iterdir()):
            match = self._FILENAME_RE.match(path.name)
            if not match:
                continue
            version, name = int(match.group(1)), match.group(2)
            if version in found:
                raise MigrationError(
                    f"duplicate migration version {version}: "
                    f"{found[version].path.name} and {path.name}"
                )
            found[version] = Migration(version, name, path)
        return [found[v] for v in sorted(found)]

    def pending(self) -> list[Migration]:
        applied = set(self.applied_versions())
        return [m for m in self.discover() if m.version not in applied]

    def rollback_candidates(self, target: int) -> list[Migration]:
        """Applied migrations with version > target, newest first."""
        by_version = {m.version: m for m in self.discover()}
        candidates = []
        for version in sorted(self.applied_versions(), reverse=True):
            if version > target:
                if version not in by_version:
                    raise MigrationError(
                        f"applied version {version} has no migration file"
                    )
                candidates.append(by_version[version])
        return candidates

    # ------------------------------------------------------------ loading

    @staticmethod
    def _load(migration: Migration) -> ModuleType:
        spec = importlib.util.spec_from_file_location(
            f"_migration_{migration.version}_{migration.name}", migration.path
        )
        if spec is None or spec.loader is None:
            raise MigrationError(f"cannot load migration {migration.path}")
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
        for attr in ("up", "down"):
            if not callable(getattr(module, attr, None)):
                raise MigrationError(
                    f"{migration.path.name} does not define {attr}(conn)"
                )
        return module

    # ----------------------------------------------------------- commands

    def upgrade(self) -> list[Migration]:
        """Apply all pending migrations in order, one transaction each."""
        applied_now = []
        for migration in self.pending():
            module = self._load(migration)
            self.conn.execute("BEGIN IMMEDIATE")
            try:
                module.up(self.conn)
                self.conn.execute(
                    f"INSERT INTO {self.VERSION_TABLE} (version, applied_at) "
                    "VALUES (?, ?)",
                    (migration.version, _utcnow_iso()),
                )
                self.conn.execute("COMMIT")
            except Exception as exc:
                self.conn.execute("ROLLBACK")
                raise MigrationError(
                    f"migration {migration.label} failed: {exc}"
                ) from exc
            applied_now.append(migration)
        return applied_now

    def downgrade(self, target: int) -> list[Migration]:
        """Roll back migrations with version > target, newest first."""
        rolled_back = []
        for migration in self.rollback_candidates(target):
            module = self._load(migration)
            self.conn.execute("BEGIN IMMEDIATE")
            try:
                module.down(self.conn)
                self.conn.execute(
                    f"DELETE FROM {self.VERSION_TABLE} WHERE version = ?",
                    (migration.version,),
                )
                self.conn.execute("COMMIT")
            except Exception as exc:
                self.conn.execute("ROLLBACK")
                raise MigrationError(
                    f"rollback of {migration.label} failed: {exc}"
                ) from exc
            rolled_back.append(migration)
        return rolled_back

    def status(self) -> str:
        """Human-readable overview of every known migration."""
        applied_at = {
            row[0]: row[1]
            for row in self.conn.execute(
                f"SELECT version, applied_at FROM {self.VERSION_TABLE}"
            )
        }
        width = max(
            [len(m.label) for m in self.discover()]
            + [len("migration"), len("003_add_archived")]
        )
        lines = [
            f"{'migration'.ljust(width)}  status     applied at",
            f"{'-' * width}  ---------  {'-' * 24}",
        ]
        for migration in self.discover():
            if migration.version in applied_at:
                status = "applied"
                when = applied_at[migration.version]
            else:
                status = "pending"
                when = "-"
            lines.append(
                f"{migration.label.ljust(width)}  {status.ljust(9)}  {when}"
            )
        current = self.current_version()
        tail = "no migrations applied" if current is None else (
            f"current version: {current:03d}"
        )
        return "\n".join(lines + ["", tail])


def _utcnow_iso() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

