"""003: add notes.archived (default 0) and backfill existing rows."""


def up(conn):
    conn.execute(
        "ALTER TABLE notes ADD COLUMN archived INTEGER NOT NULL DEFAULT 0"
    )
    # Backfill: make sure every pre-existing row is explicitly not archived.
    conn.execute("UPDATE notes SET archived = 0 WHERE archived IS NULL")
    count = conn.execute(
        "SELECT COUNT(*) FROM notes WHERE archived IS NULL"
    ).fetchone()[0]
    if count:
        raise RuntimeError(f"backfill left {count} rows with NULL archived")


def down(conn):
    conn.execute("ALTER TABLE notes DROP COLUMN archived")

